interface PickedBone {
    bone: number;
    /** Its name for people: 'left forearm'. */
    label: string;
    /** How many blobs it moves at all. */
    blobs: number;
}

interface StageOptions {
    offscreen?: boolean;
    /** Builds each world with live lights (`setLights`), as Scan Studio does. */
    lights?: boolean;
    /** Uses the WebGL 2 backend even where WebGPU would start: for testing the fallback. */
    webgl?: boolean;
}

class Stage {
    readonly renderer: THREE.WebGPURenderer;
    readonly backend: 'webgpu' | 'webgl';
    orbit: Orbit;
    playing: boolean;
    speed: number;
    /**
     * Held frames: above 0, the pose only moves on every `step` seconds and the picture is left alone in between,
     * like animation drawn at a few frames a second. In pixel mode that is what stops edges crawling.
     */
    step: number;
    /** Called once, after the first frame with a creature in it has been drawn. */
    onFirstFrame?: () => void;
    mode: SkinMode;
    static start(display: HTMLCanvasElement, opts?: StageOptions): Promise<Stage>;
    get blobCount(): number;
    /** Shows a creature, replacing the last one, and plays `clip` on it. */
    setActor(actor: Actor, clip?: Clip): void;
    /** Which depth sort the world uses: the counting sort, or the exact radix sort (slower; ties always in one order). */
    get sortKind(): "bins" | "radix";
    setSort(kind: 'bins' | 'radix'): void;
    setClip(clip?: Clip): void;
    /** Poses from the time instead of a clip; `t` starts at `from` seconds. */
    setPoser(poser?: (sk: Skeleton, t: number) => void, from?: number): void;
    /** Loose parts that swing after the body while a move plays (a `Swing` made for this actor's skeleton), or none. */
    setSwing(swing?: {
        update(sk: Skeleton, dt: number): void;
        reset(): void;
    }): void;
    /** The morphs' weights while no clip keys them (the clip's own weights win while it plays). */
    setMorphWeights(w: ArrayLike<number>): void;
    /** After the actor's blobs were changed in place (a poser may do it each frame): the engine takes them again. */
    refresh(): void;
    /** Seconds into the clip, or the time a poser is showing. */
    get time(): number;
    setMode(m: SkinMode): void;
    /** Distance fog toward `color` (linear) from `near` to `far` units from the camera (`far` 0 is none); kept for the next actor too. */
    setFog(color: [number, number, number], near: number, far: number): void;
    /** Live lights on the world (needs the `lights` option); kept for the next actor too. */
    setLights(lights: PointLight[], ambient?: number): void;
    /** A floor `size` across in half-unit squares, so the grid shows how big each creature is. */
    setFloor(size: number): void;
    setShow(s: Show): void;
    /**
     * Pixel mode on (with a look) or off. `size` is how many CSS pixels across
     * one art pixel is; the art is that many times smaller than the view.
     */
    setPixels(look?: PixelLook, size?: number): void;
    /** Pixel mode's art size in pixels, once a frame has been drawn. */
    get artSize(): {
        width: number;
        height: number;
    } | undefined;
    /** Pixel mode's last frame as it was drawn small, and as finished art (exactly in the look's colors): for tests and for saving. */
    pixelFrames(): Promise<{
        small: Frame;
        art: Frame;
        before?: Frame;
        parts?: Frame;
    } | undefined>;
    /**
     * The bone under a point on the view (CSS pixels from its top left), as the creature stands now:
     * the bone that holds most of the blob the pointer is on. Undefined when the pointer is off the creature.
     */
    pick(x: number, y: number): PickedBone | undefined;
    /** The line from the camera through a point on the view (CSS pixels from its top left), in world space. */
    rayAt(x: number, y: number): {
        origin: [number, number, number];
        direction: [number, number, number];
    } | undefined;
    /** The bone under a point on the view (CSS pixels from its top left) and where the pointer meets it, in world space. */
    hitAt(x: number, y: number): {
        bone: number;
        point: [number, number, number];
    } | undefined;
    /** What the page says about a bone. */
    boneInfo(bone: number): PickedBone | undefined;
    /** Lights up one bone and the blobs it moves (or none). */
    highlight(bone?: number): void;
    invalidate(frames?: number): void;
    /** Offscreen only: draws the frame `t` seconds into the clip and copies it to the page. */
    frame(t: number): Promise<void>;
    /**
     * Draws the creature on show as a pixel-art sprite sheet (bakeSheet.ts), with
     * the floor and bones out of the picture and the live view paused, then puts
     * the view back as it was.
     */
    bake(moves: SheetMove[], opts: BakeOptions, progress?: (done: number, total: number) => void): Promise<BakedSheet>;
    dispose(): void;
}

interface Actor {
    blobs: Blobs;
    skin: Skin;
    skeleton: Skeleton;
    /** Blend shapes (from an opened .glb): a clip's weights, or `setMorphWeights` while none play, reshape the blobs on the CPU. */
    morphs?: Morph[];
}

interface Actor {
    blobs: Blobs;
    skin: Skin;
    skeleton: Skeleton;
    /** Which part of the actor each blob belongs to (as `buildBody` and `voxelBody` give it): what `SplatWorld.parts` draws. Left out, the actor is one part. */
    partOf?: ArrayLike<number>;
    /**
     * How much of each of the first four live lights a blob can see, four bytes a blob (255 sees it all): baked lamp
     * shadows (voxel.ts `lamps`). The light pass scales light k by byte k, so a flickering lamp's shadows flicker with it.
     * Left out, every light reaches every blob.
     */
    seen?: Uint8Array;
    /** Blend shapes (morph.ts), set with `SplatWorld.setMorphWeights`: on WebGPU a pass before the deform reshapes the blobs; on WebGL the CPU does and uploads them. */
    morphs?: Morph[];
}

interface EngineOptions {
    /** Depth buckets for the counting sort. More buckets, fewer ties between blobs that are close in depth. */
    bins?: number;
    /**
     * 'bins' (the default): a counting sort over `bins` depth buckets, small buckets settled into index order.
     * 'radix': a stable radix sort over 2²⁴ depth steps (radix.ts), every tie in index order however many share it.
     */
    sort?: 'bins' | 'radix';
    mode?: SkinMode;
    /** Live lights (`setLights`): each blob is lit every frame from its normal. Off unless asked for, as it costs a pass. */
    lights?: boolean;
    /** Paint edits (`setEdits` with op 'paint'): needs the same color pass as lights. Cuts work without it. */
    paint?: boolean;
}

interface PointLight {
    position: [number, number, number];
    /** Linear RGB, times its strength: [1, 0.6, 0.3] is a torch at full strength. */
    color: [number, number, number];
    /** Its reach: about a quarter strength at this distance, and gone by twice it. */
    range: number;
    /** Whether it casts shadows (`shadow.ts`): blobs between a blob and the light take some of it. Off unless set. */
    shadow?: boolean;
}

class SplatWorld extends Mesh {
    readonly isSplatWorld = true;
    readonly count: number;
    readonly actors: Actor[];
    readonly boneCount: number;
    mode: SkinMode;
    /** Set by the WebGL backend path, read by tests: did the last frame skin on the CPU? */
    cpuPath: boolean;
    /** Milliseconds the CPU spent in the last frame (WebGL path only): moving centers, sorting, both. */
    cpuMs: number;
    cpuSkinMs: number;
    cpuSortMs: number;
    /** While true, rendering draws the last frame's blobs without moving or sorting them (for timing the draw alone, and for a second draw of the same frame such as the map of parts). */
    hold: boolean;
    /**
     * While true, the draw is a map of parts, not a picture: every blob is a hard disc in its part's own flat color
     * (red and green hold the part's number plus one, blue the actor's), with no light, fog or soft edge, so where two
     * parts meet the color changes exactly. Pixel mode draws it for the lines between parts.
     */
    get parts(): boolean;
    set parts(on: boolean);
    /**
     * While true, the draw is a depth map: every blob a hard disc (as in the map of parts) whose color is its distance in
     * front of the camera, in units, in all three channels. Drawn after the frame's own render with `hold`, the frame's
     * sort puts the nearest disc last, so each pixel keeps the nearest depth. `SplatDepth` (depth.ts) draws it.
     */
    get depthMap(): boolean;
    set depthMap(on: boolean);
    /**
     * Level of detail: while set, each actor draws a share of its blobs by how big it is on screen (`detailFor`),
     * the rest grown to cover for them. Off (every blob drawn) unless asked for; turning it off draws every blob again.
     */
    get autoDetail(): DetailRule | false;
    set autoDetail(rule: DetailRule | false);
    readonly bounds: Sphere;
    /**
     * Distance fog: blobs fade toward `color` (linear RGB) from `near` to `far`
     * in front of the camera, so a scene can end in mist instead of an edge.
     * Off while `far` is 0.
     */
    readonly fog: Fog;
    /** Live lighting, when the world was made with `lights: true`. */
    readonly lighting?: Lighting;
    constructor(actors: Actor[], { bins: wantBins, sort: sortKind, mode, lights, paint }?: EngineOptions);
    /** Fades blobs to `color` (linear RGB, 0–1) between `near` and `far` units from the camera; `far` 0 turns it off. */
    setFog(color: [number, number, number], near: number, far: number): void;
    /**
     * Lights the blobs with up to MAX_LIGHTS point lights, on top of `ambient`
     * times their own (baked) color. Each blob's normal is its flattest axis, so
     * a light reaches the side of a surface that faces it. Needs `lights: true`.
     */
    setLights(lights: PointLight[], ambient?: number): void;
    /**
     * Cuts and paints by shape, live (edit.ts): up to MAX_EDITS spheres or boxes in world space, tested against where each
     * blob is now. A cut blob gets no size; a painted one is mixed toward the paint before any light (needs `paint: true`
     * or `lights: true`). Replaces the edits before; [] clears them.
     */
    setEdits(edits: readonly ShapeEdit[]): void;
    /** Sets an actor's morph weights (one per morph, 0–1); the blobs are reshaped next frame. */
    setMorphWeights(actor: Actor | number, weights: ArrayLike<number>): void;
    /** Call after posing any skeleton. */
    markPosed(): void;
    /** Draws `keep` (0–1) of an actor's blobs, each grown to cover for the rest. 1 draws them all. `autoDetail` overrides it each frame. */
    setDetail(actor: Actor | number, keep: number): void;
    /** The share of each actor's blobs being drawn. */
    get detail(): number[];
    /**
     * Takes the actors' blobs again after they were changed in place: centers, shapes, colors and opacities, for blobs
     * that something other than a bone moves (a shape shift). The counts, the bones and the weights must be as they were.
     */
    refresh(): void;
    /**
     * Takes one actor's colors and opacities again after they were changed in place, when nothing moved
     * (a floor that scorches): only the color buffer goes up again.
     */
    recolor(actor: Actor): void;
    /**
     * For tests: the GPU's grid of shadows against the CPU twin's, built from the CPU's deform of the same frame
     * (WebGPU, with a light casting). Returns the cells that differ by more than one unit and the total in each.
     */
    checkShadows(renderer: Renderer): Promise<{
        differ: number;
        gpuTotal: number;
        cpuTotal: number;
    }>;
    /**
     * The frame's GPU work in stages, so a timer can wait between them. Each
     * assumes the ones before it ran: deform (bones → world), then project
     * (world → screen, plus sort keys), then order (the sort itself).
     */
    stages(renderer: Renderer, camera: Camera): {
        deform: () => void;
        project: () => void;
        order: () => void;
    };
    /**
     * The CPU twin of the deform pass: every blob's world center (4 floats) and
     * covariance (6). It reads the same byte weights the GPU does, so the two agree.
     */
    deformCPU(): {
        center: Float32Array<ArrayBuffer>;
        cov: Float32Array<ArrayBuffer>;
    };
    /**
     * Reads back what the GPU deform wrote and compares it with the CPU twin.
     * Returns the largest differences in center (world units) and covariance.
     */
    checkAgainstCPU(renderer: Renderer): Promise<{
        center: number;
        cov: number;
        covScale: number;
    }>;
    /**
     * Reads back the colors the GPU gave each blob by angle and checks them against `viewColor` (sh.ts) for the view
     * last drawn: the largest gap per channel, 0–1. Only meaningful with no lights and no paint (the pass's output is
     * the lit color). WebGPU only.
     */
    checkViewColors(renderer: Renderer): Promise<number | null>;
    /** Reads back the GPU sort and checks it: every blob drawn once, farthest first. */
    /** Which depth sort this world was built with. */
    get sortKind(): 'bins' | 'radix';
    checkSort(renderer: Renderer): Promise<{
        missing: number;
        outOfOrder: number;
        unsettled: number;
        biggest: number;
    }>;
    /** The order the last sort produced (drawn first is farthest). Only up to date on the CPU path. */
    get order(): Uint32Array;
    dispose(): void;
}

interface Orbit {
    target: [number, number, number];
    distance: number;
    /** Degrees around the vertical axis; 0 looks from +Z. */
    azimuth: number;
    /** Degrees above the horizon. */
    elevation: number;
}

class Blobs {
    count: number;
    center: Float32Array;
    scale: Float32Array;
    quat: Float32Array;
    color: Float32Array;
    opacity: Float32Array;
    /**
     * Color by angle, when the blobs have it: `shDegree` 1–3, and per blob
     * `shTerms` triples (r, g, b for each spherical harmonic term after the
     * first, in the files' order and signs: see `viewColor` in sh.ts). Blobs
     * without it have degree 0 and no array.
     */
    shDegree: number;
    sh: Float32Array | null;
    constructor(capacity?: number);
    get capacity(): number;
    /** Rest terms per blob: 0, 3, 8 or 15. */
    get shTerms(): number;
    /** Gives the blobs color by angle up to `degree` (0 removes it), keeping the terms they already have. */
    setSHDegree(degree: number): void;
    push(b: Blob): number;
    set(i: number, b: Blob): void;
    get(i: number): Blob;
    /** Keeps the blobs where `keep(i)` is true, in order. Returns how many were removed. */
    filter(keep: (i: number) => boolean): number;
    clone(): Blobs;
    /** Bytes held by the used part, for capping undo history. */
    get bytes(): number;
}

interface Bone {
    name: string;
    parent: number;
    head: Vec3;
    /** Where the bone ends in the rest pose, for drawing it. A bone with children points at its first child when this is missing. */
    tail?: Vec3;
}

class Skeleton {
    readonly bones: Bone[];
    /** Pose: local rotation per bone (x, y, z, w). */
    readonly rotation: Float32Array;
    /** Pose: local offset per bone, added to its rest offset from the parent. */
    readonly offset: Float32Array;
    /** Pose: local uniform scale per bone, about its head; children inherit it. */
    readonly size: Float32Array;
    /** Pose: uniform scale of the root (bone 0), on top of its `size`. */
    rootScale: number;
    /** Where the actor stands: added to every root bone, and kept by `reset()` (a pose isn't a placement). */
    readonly place: Float32Array<ArrayBuffer>;
    /** Output, per bone: skin matrix (16), skin rotation quaternion (4), skin uniform scale (1). */
    readonly matrix: Float32Array;
    readonly quat: Float32Array;
    readonly scale: Float32Array;
    /** Posed world position of each bone's head, for drawing the rig. */
    readonly posedHead: Float32Array;
    constructor(bones: Bone[]);
    get count(): number;
    index(name: string): number;
    setRotation(bone: number, q: ArrayLike<number>): void;
    /** Back to the rest pose. */
    reset(): void;
    update(): void;
}

interface Skin {
    joints: Uint8Array;
    weights: Float32Array;
}

function skinBlob(center: ArrayLike<number>, scale: ArrayLike<number>, quat: ArrayLike<number>, joints: ArrayLike<number>, weights: ArrayLike<number>, rig: {
    matrix: ArrayLike<number>;
    quat: ArrayLike<number>;
    scale: ArrayLike<number>;
}, mode: SkinMode, outCenter: Float32Array, oc: number, outCov: Float32Array, ov: number): void;

function posedPoint(sk: {
    matrix: ArrayLike<number>;
}, bone: number, p: ArrayLike<number>): [number, number, number];

entries.doc:
Mixing moves: what three.js's AnimationMixer does for meshes, for our
skeletons. A move here is a function of time that poses a skeleton (as the
zoo's moves and the elf's walk are), so a mix poses the skeleton once per
move and blends the results.

- `takePose` / `putPose` copy a pose out and back;
- `blendPose` moves the pose now part of the way toward or away from another
  (rotations by the short way, offsets and sizes straight);
- `addPose` lays a move on top as a change from a reference pose, so a nod
  or a breath can ride on any walk;
- `Mixer` plays named moves with weights and crossfades between them.

entries.code:
interface Pose {
    rotation: Float32Array;
    offset: Float32Array;
    size: Float32Array;
}

interface MixMove {
    name: string;
    /** Seconds a loop takes; the move's time wraps at it. Leave it out for a move that runs on (a pose held, or a one-off read with `elapsed`). */
    seconds?: number;
    pose: (sk: Skeleton, t: number) => void;
}

class Mixer {
    constructor(moves: MixMove[]);
    /** Fades `name` in over `fade` seconds (0: at once) and everything else out. `restart` sets its clock back to 0. */
    play(name: string, fade?: number, restart?: boolean): void;
    /** Sets weights directly (they are scaled to sum to 1), as a run blends with speed. No fade. */
    setWeights(weights: Record<string, number>): void;
    /** How much of a move is in the mix now. */
    weight(name: string): number;
    /** A move's own time, in seconds since it started (wrapped by `seconds` when it loops). */
    time(name: string): number;
    /** Moves a clock on by its own amount (a walk at the pace of the feet; negative backs up). */
    advance(name: string, dt: number): void;
    /** Moves every clock on by `dt` (times `speed[name]` where given) and every weight toward its target. */
    update(dt: number, speed?: Record<string, number>): void;
    /** Poses `sk` as the blend of every move with weight, in the order they were given; each move starts from the rest pose. Doesn't call `update()` on the skeleton. */
    apply(sk: Skeleton): void;
}

interface TwoBoneOptions {
    /** World direction the knee or elbow should point when the limb gives no bend of its own (it is straight). */
    pole?: Vec3;
    /** 0 leaves the limb as it is, 1 reaches all the way. */
    amount?: number;
}

interface LookOptions {
    /** The direction the bone looks along at rest, in world space (a creature facing +z looks along +z). */
    forward?: Vec3;
    /** 0 leaves the bone, 1 turns it all the way. */
    amount?: number;
    /** The most it turns from where it points now, in radians, so a head never spins round. */
    limit?: number;
}

interface Leg {
    upper: string;
    lower: string;
    foot?: string;
    tip?: Vec3;
    pole?: Vec3;
}

interface PlantOptions {
    /** 0 leaves the walk as it is (on flat ground), 1 plants it fully. */
    amount?: number;
    /** Lower the hips so the lower foot can reach (true), or leave them and let that leg hang. */
    hips?: boolean;
    /** Tilt each foot to the slope under it. */
    tilt?: boolean;
}

interface Planted {
    /** How far the hips moved down (negative) or up. */
    hipShift: number;
    /** Per leg: the ankle's target and how far it ended from it. */
    legs: {
        target: Vec3;
        miss: number;
        ground: number;
    }[];
}

interface StepFoot {
    /** Where the foot stands under the body at rest, in the body's frame: x to its left, z ahead. */
    home: [number, number];
}

interface StepOptions {
    /** How far a planted foot may fall from its home under the body before it steps, meters. */
    reach: number;
    /** Seconds a step takes in the air, at most: a body moving fast enough to cover two `reach`es in that time steps
     * quicker, so the feet still under it don't fall far behind before the step lands. */
    duration: number;
    /** How high a step lifts the foot at its middle, meters. */
    lift: number;
    /** Which feet step together: a list of groups of foot indices (each foot in one). Left out, each foot alone. */
    groups?: number[][];
    /** How far ahead along the body's motion a step aims past where home will be when it lands, in seconds of that
     * motion (half a second by default), never more than `reach`: a slow walk takes short steps, a fast one lands a
     * whole `reach` ahead so the foot spends its time under the body evenly before and behind. */
    lead?: number;
    /** Below this distance from home a still body's foot is left where it is; above it, it steps home to stand square. */
    settle?: number;
    /** Radians the body may turn from where it faced when a foot landed before that counts as the whole `reach`
     * (so turning on the spot steps even when a narrow stance hardly moves the feet). */
    twist?: number;
}

interface StepBody {
    x: number;
    z: number;
    /** Turned from +z toward +x, radians. */
    heading: number;
    vx: number;
    vz: number;
    /** Radians a second. */
    turn: number;
}

interface FootState {
    /** Where the foot stands, or stood when it lifted. */
    at: [number, number];
    /** Where a foot in the air lands. */
    to: [number, number];
    /** How far through its step, 0 to 1, or −1 while planted. */
    t: number;
    /** Which way the body faced (heading) when the foot last landed, or will face where it lands. */
    facing: number;
    /** Which way the foot faced when it lifted, so a foot in the air can turn from it to `facing`. */
    faced: number;
    /** Seconds this step takes in the air. */
    span: number;
}

class Steps {
    readonly feet: FootState[];
    readonly opts: Required<StepOptions>;
    /** Steps taken so far, by every foot. */
    taken: number;
    constructor(feet: StepFoot[], body: StepBody, opts: StepOptions);
    /** Where foot i stands under the body, `ahead` seconds along its motion. */
    home(i: number, b: StepBody, ahead?: number): [number, number];
    /** How far foot i has fallen (or will have, `ahead` seconds on) from where it should stand under the body: its distance from home plus its turn, as a share of `twist` times `reach`. */
    off(i: number, b: StepBody, ahead?: number): number;
    /** Which way foot i faces now: as it landed, or partway round to where it lands. */
    turned(i: number): number;
    /** The foot is in the air. */
    stepping(i: number): boolean;
    /** Moves the plan on by `dt` with the body now at `b`. Returns each foot's place: x, height above the ground, z. */
    update(b: StepBody, dt: number): Vec3[];
    /** Puts every foot back under the body, planted (after a jump in place, or a new start). */
    reset(b: StepBody): void;
}

interface Chain {
    bones: readonly string[];
    /** How loosely each point after the first follows the move: one number for all, or one per point. */
    follow: number | readonly number[];
    /** A soft link from each point to the one after next, so a chain bends but doesn't fold back (compliance). */
    bend?: number;
}

interface SwingSpec {
    /** What swings, for a sentence: "tail", "cloak and plait". */
    parts: string;
    chains: readonly Chain[];
    /** Links between chains, as [chain, point, chain, point, compliance]: a cloak's two halves, say. */
    ties?: readonly (readonly [number, number, number, number, number])[];
    /** The body, as posed now, as capsules the points stay out of. */
    body?: (sk: Skeleton) => Capsule[];
    /** How quickly swinging dies away, per second (the solver's 1.5 if left out). Stiff tails driven fast want more, or they ring. */
    damping?: number;
    /** A pinned point that moves further than this in a frame means the creature was moved, not walked: start still. */
    jump?: number;
    /** Runs after the bones are turned, before the pose is updated: the elf clears its cloak of the legs. */
    after?: (sk: Skeleton) => void;
}

class Swing {
    readonly sim: Xpbd;
    readonly spec: SwingSpec;
    constructor(sk: Skeleton, spec: SwingSpec);
    /** Moves the parts on by `dt` seconds once the move is posed and the creature placed, and turns their bones. Leaves the pose updated. */
    update(sk: Skeleton, dt: number): void;
    /** Forgets the motion: the next update starts still, where the move puts everything. */
    reset(): void;
}

interface Capsule {
    a: Vec3;
    b: Vec3;
    r: number;
}

class Xpbd {
    readonly n: number;
    readonly pos: Float64Array;
    readonly vel: Float64Array;
    readonly invMass: Float64Array;
    readonly links: Link[];
    /** Where the animation puts each point, and how loosely it follows (Infinity: not at all). */
    readonly goal: Float64Array;
    readonly goalCompliance: Float64Array;
    capsules: Capsule[];
    gravity: Vec3;
    /** Share of velocity lost per second. */
    damping: number;
    constructor(n: number);
    /** Keeps `a` and `b` at `rest` (their distance now if not given). */
    link(a: number, b: number, compliance?: number, rest?: number): void;
    distance(a: number, b: number): number;
    /** Puts point `i` at `p`, still. */
    place(i: number, p: ArrayLike<number>): void;
    /** Pins point `i`: from now on it moves only where `pin` sends it. */
    fix(i: number): void;
    /** Where pinned point `i` should be at the end of the next `advance`; it gets there evenly over the frame. */
    pin(i: number, p: ArrayLike<number>): void;
    /** Where the animation wants point `i`, and how loosely it follows. */
    follow(i: number, p: ArrayLike<number>, compliance: number): void;
    /** Runs whole steps for `dt` seconds (carrying the rest); returns how many ran. */
    advance(dt: number): number;
    /** Kinetic energy, for a unit mass per free point. */
    energy(): number;
    /** Every point still, where it is (after a jump, say). */
    settle(): void;
}

interface MorphTarget {
    delta: Float32Array;
    grad: Float32Array;
}

interface Morph {
    name: string;
    /** Reached in turn, evenly spaced, as the weight goes 0 → 1; the last is the full shape. */
    targets: MorphTarget[];
}

entries.doc:
The rest blobs with the morphs applied, into `out` (as many blobs as `rest`;
colors and opacities are left alone). 'centers' moves the centers only, as a
mesh morph would; 'shape' also pushes each blob's shape through J.

entries.code:
interface PickHit {
    /** Index into the actors given. */
    actor: number;
    blob: number;
    /** Distance along the ray (in units of the direction's length). */
    t: number;
    /** Where the ray meets the blob, in world space. */
    point: [number, number, number];
    /** The bone that holds most of the blob. */
    bone: number;
    /** Its part (`Actor.partOf`), or 0 when the actor has none. */
    part: number;
}

interface PickOptions {
    /** How far out a blob counts, in standard deviations (2 is about where it fades to nothing). */
    k?: number;
    /** Blobs fainter than this are looked through. */
    minOpacity?: number;
}

interface Shape {
    /** Distance to the surface: negative inside. */
    sdf: (x: number, y: number, z: number) => number;
    /** A box that holds the whole shape. */
    min: Vec3;
    max: Vec3;
    /**
     * For a shape made of many pieces (the bricks of a wall, the posts of a fence, the columns of a basalt
     * causeway): which piece a surface point belongs to, as a whole number 0 or more, or -1 for what lies between
     * them (mortar). The `pieces` paint gives every piece a color of its own.
     */
    pieceAt?: (p: Vec3) => number;
}

interface VoxelPart {
    shape: Shape;
    /** Color (0–1, sRGB) or color at a surface point given its outward normal. */
    color: Vec3 | ((p: Vec3, n: Vec3) => Vec3);
    /** The bone that carries it. */
    bone: string;
    /** Unlit and casting no shadow: lamps, windows, beams of light. */
    glow?: boolean;
    opacity?: number;
    /** Casts no shadow on other parts (thin things far from the ground, like birds). */
    noShadow?: boolean;
    /** A color (sRGB, 0–1) that gathers in its hollows and creases, as moss or dirt does. Needs the light's `crevice` to find them. */
    grime?: Vec3;
    /** Takes none of the scene's `cover`: water, glass, anything that moves through it or was just made. */
    bare?: boolean;
    /** Little drawn marks over the surface: see Ink. */
    ink?: Ink;
    /** Water, ice or glass: see Glass. Needs the spec's `eye`. */
    glass?: Glass;
    /**
     * Dabs that follow the form: 0 leaves each cell a round disc; up to 1 draws it as a stroke along the level line
     * round the shape, as a painter's brush goes round a pot or a trunk. Seen as blobs it reads as brushwork; in pixel
     * mode it barely shows.
     */
    strokes?: number;
}

interface Glass {
    /** How much of what is behind shows through: 0 to 1. */
    see?: number;
    /** How much it mirrors, looked at straight on; more at a glancing look. 0 to 1. */
    mirror?: number;
    /** Only its upturned faces: a pond cut as one slab whose sides are earth. */
    top?: boolean;
}

interface Ink {
    kind: InkKind;
    amount?: number;
    color?: Vec3;
}

interface Cover {
    kind: 'snow' | 'moss' | 'dust';
    /** sRGB, 0–1. */
    color: Vec3;
    /** 0–1: how much of the scene it takes, from a dusting to most of what faces up. */
    amount: number;
}

interface LooseBlob {
    center: Vec3;
    /** Its radii along x, y and z. */
    scale: Vec3;
    color: Vec3;
    opacity: number;
    bone: string;
}

interface Beam {
    from: Vec3;
    to: Vec3;
    /** Its radius. */
    r: number;
    color: Vec3;
    /** 0–1. */
    strength: number;
}

interface VoxelLight {
    /** Direction toward the sun. */
    dir: Vec3;
    /** Light that reaches everywhere, 0–1. */
    ambient: number;
    /** How dark a cast shadow is: 0 leaves no shadow, 1 leaves only the ambient light. */
    shadow: number;
    /** How far shade turns its hue toward cool violet and full sun toward warm yellow, as a painter's ramp does: 0 only darkens. */
    ramp?: number;
    /** How much surfaces shut in by others (corners, cracks, the foot of a wall) darken: 0 to 1. */
    crevice?: number;
    /** How much sharp outer edges lighten, as worn stone and wood do: 0 to 1. */
    wear?: number;
    /** How much color surfaces throw onto what faces them, as a red wall warms the floor beside it: 0 to 1. */
    bounce?: number;
}

interface VoxelSpec {
    bones: Bone[];
    parts: VoxelPart[];
    /** Grid cell size in world units: one blob per surface cell. */
    spacing: number;
    light?: Partial<VoxelLight>;
    /** Skip blocks of cells far from a surface: much quicker for big smooth shapes, sound only for honest distance functions (sculpt.ts). */
    blocks?: boolean;
    /**
     * Keep the outermost layer one cell thick in true distance, not in the shape's own units. A shape pushed in and
     * out (`displace`) can have a distance that changes faster than one unit per unit; read raw, its layer comes out
     * thinner than a cell and leaves holes you see the far side through. Creatures (sculpt.ts) turn this on.
     */
    trueShell?: boolean;
    /** How deep (world units) a cell may sit inside a neighbor on its bone and still be made: a skirt that keeps a joint closed as parts move. */
    keepBuried?: number;
    /**
     * A disc's radius (its blob's scale across the surface) as a share of `spacing`. The default leaves the grid
     * crisp for pixel mode, which cuts alpha; drawn smooth, discs that small let about a tenth of what lies behind
     * show between them, so a creature seen as blobs wants them wider.
     */
    disc?: number;
    /** Blobs placed as they are, after the cut ones: see LooseBlob. */
    loose?: LooseBlob[];
    beams?: Beam[];
    /** Snow, moss or dust over every part that isn't `bare` or `glow`: see Cover. */
    cover?: Cover;
    /**
     * Where the eye goes: within `r` of `at` the grid is as fine as `spacing`; further out it is twice as coarse, with
     * discs twice the size, so the subject keeps its detail and the rest is painted broadly in a quarter of the blobs. Only parts at least
     * eight cells across every way go coarse: a thinner one could miss every coarse cell.
     */
    focus?: {
        at: Vec3;
        r: number;
    };
    /** Where `glass` parts are looked at from: the scene's camera. */
    eye?: Vec3;
    /** The sky a `glass` part mirrors where its mirror line meets nothing: [overhead, at the horizon]. Dark when left out. */
    sky?: [Vec3, Vec3];
    /**
     * Lamps whose shadows are baked, in the order of the live lights they stand for (at most four; a gap is a light
     * that casts none): for each blob, how much of lamp k it can see goes in byte k of `seen`, and the engine's live
     * light pass scales that light by it, so a lamp's shadows flicker with it and cost nothing a frame.
     */
    lamps?: (Lamp | null | undefined)[];
}

interface Lamp {
    at: Vec3;
    /** How far its light reaches: blobs further off are not looked at (their byte stays full). */
    reach: number;
}

const PAINTED: {
    ramp: number;
    crevice: number;
    wear: number;
};

function letterGrid(at: Vec3, size: number, layers: string[][]): Shape & {
    letterAt: (p: Vec3, n: Vec3) => string | undefined;
};

interface SculptPart {
    shape: Shape;
    /** Color (0–1, sRGB) or color at a surface point given its outward normal. */
    color: Vec3 | ((p: Vec3, n: Vec3) => Vec3);
    /** The bones that move it: each cell is weighted by its distance to each. */
    bones: string[];
    group?: string;
    glow?: boolean;
    opacity?: number;
    noShadow?: boolean;
    /** How far its weights spread from each bone, if not the creature's `blend`. */
    blend?: number;
}

interface SculptSpec {
    bones: Bone[];
    parts: SculptPart[];
    /** How far (in world units) a cell's weight spreads from a bone. */
    blend: number;
    light?: Partial<VoxelLight>;
    /**
     * How deep (world units) a part's skin goes on inside a neighbor of its group. 0 cuts it off at the neighbor's
     * surface; a little keeps a neck closed where it meets a turning head.
     */
    skirt?: number;
}

interface Sculpted extends Creature {
    partOf: Uint16Array;
    spacing: number;
}

function toCount<T extends {
    blobs: Blobs;
}>(cut: (spacing: number) => T, count: number, probe: number): T;

function joinBuilt(a: {
    blobs: Blobs;
    skin: Skin;
}, b: {
    blobs: Blobs;
    skin: Skin;
}): {
    blobs: Blobs;
    skin: Skin;
    from: number;
};

function scales(p: ArrayLike<number>, a: number): {
    out: number;
    id: number;
};

interface Creature {
    blobs: Blobs;
    skin: Skin;
    skeleton: Skeleton;
}

interface Part {
    shape: Shape;
    /** Color at a point on the surface, given its outward normal and `u`, how far along a tube or fill (0–1). */
    color: Vec3 | ((p: Vec3, n: Vec3, u: number) => Vec3);
    /** The bones that move it, nearest first is not needed: each blob is weighted by its distance to each. */
    bones: string[];
    /** Blobs per unit area, relative to the rest. */
    density?: number;
    /** Blob size, relative to the rest. */
    size?: number;
    /** Opacity, or opacity at a point given how far along it is (as for `color`). */
    opacity?: number | ((p: Vec3, u: number) => number);
    /** Unlit: the color as given, for eyes and fire. */
    glow?: boolean;
    /** How far its weights spread from each bone, if not the creature's `blend`: wider for a sheet that must stretch smoothly. */
    blend?: number;
}

interface BodySpec {
    bones: Bone[];
    parts: Part[];
    /** How far (in world units) a blob's weight spreads from a bone: about a tenth of a limb. */
    blend: number;
}

interface Built extends Creature {
    /** Which part each blob came from. */
    partOf: Uint16Array;
    /** How much of each baked lamp a blob can see, four bytes a blob (voxel.ts `lamps`); left out, every lamp is seen. */
    seen?: Uint8Array;
}

interface Fur {
    /** How long a strand is, in world units. */
    length: number;
    /** Which way the coat lies at a surface point. Only its part along the skin counts. */
    flow: Vec3 | ((p: Vec3, n: Vec3) => Vec3);
    /** How far strands stand up from the skin, in radians: 0 lies flat. */
    lift?: number;
    /** How far strands stray from the flow, in radians either way. */
    wild?: number;
    /** Strands here for each strand on plain fur of the same area (a ruff is thicker). */
    density?: number;
    /** A factor on the length at a surface point: a ruff that grows longer toward the chest. */
    long?: (p: Vec3, n: Vec3) => number;
    /** How dark the undercoat (the shell under the strands) is, as a share of its color. */
    under?: number;
    /** Strand color at a point, if not the skin's own (a pale tip on dark fur). Lit as the skin under it is. */
    color?: (p: Vec3, n: Vec3) => Vec3;
}

interface FurryPart extends SculptPart {
    fur?: Fur;
}

interface WallSpec {
    /** The foot of the wall at one end and at the other; the wall stands on `from`'s height. */
    from: Vec3;
    to: Vec3;
    height: number;
    thick: number;
    /** A brick's length and height (a course), fitted so whole courses and bricks fill the wall. */
    brick?: [number, number];
    /** How far bricks sit proud or sunk and vary in size, 0 to 1. */
    jitter?: number;
    /** How much of the top has fallen, 0 (whole) to 1 (down to the ground in places). */
    ruin?: number;
    /** The share of bricks gone from the face, showing the mortar core behind, 0 to 0.5. */
    missing?: number;
    /** Bricks lying at the foot of the wall, fallen from its top. */
    fallen?: number;
    seed: number;
}

function wallPlan(s: WallSpec): {
    f: {
        len: number;
        ux: number;
        uz: number;
        local: (x: number, y: number, z: number) => [number, number, number];
        world: (u: number, v: number, w: number) => Vec3;
    };
    rows: number;
    cols: number;
    bh: number;
    bl: number;
    topAt: (u: number) => number;
    span: (j: number, c: number) => [number, number];
    state: (j: number, c: number) => 0 | 1 | 2;
};

function fallenBricks(s: WallSpec, plan?: {
    f: {
        len: number;
        ux: number;
        uz: number;
        local: (x: number, y: number, z: number) => [number, number, number];
        world: (u: number, v: number, w: number) => Vec3;
    };
    rows: number;
    cols: number;
    bh: number;
    bl: number;
    topAt: (u: number) => number;
    span: (j: number, c: number) => [number, number];
    state: (j: number, c: number) => 0 | 1 | 2;
}): Shape[];

interface StepsSpec {
    /** The middle of the bottom step's front edge, on the ground. */
    at: Vec3;
    /** The way the flight climbs, along the ground: [x, z]. */
    dir: [number, number];
    count: number;
    rise: number;
    run: number;
    width: number;
    /** How worn: rounded noses and a hollow where feet go, 0 to 1. */
    wear?: number;
    seed: number;
}

interface FenceSpec {
    /** Where it runs, on the ground: 2 to 16 points. */
    path: Vec3[];
    /** About how far apart the posts stand; each run is cut into whole bays. */
    bay: number;
    height: number;
    /** Half a post's thickness. */
    post: number;
    /** Rails between posts, 1 to 4. */
    rails: number;
    /** How many posts lean and how far, 0 to 1. */
    lean?: number;
    /** The share of rails gone or hanging from one end, 0 to 1. */
    missing?: number;
    /** How far rails sag in the middle, 0 to 1. */
    sag?: number;
    seed: number;
}

function fencePosts(s: FenceSpec): {
    foot: Vec3;
    top: Vec3;
}[];

interface ArcadeSpec {
    from: Vec3;
    to: Vec3;
    height: number;
    thick: number;
    /** Equal bays the span is cut into: one opening each, with a pillar between. */
    bays: number;
    /** A pillar's width. */
    pillar: number;
    /** The height the arches spring from; left out, 60% of the wall. */
    spring?: number;
    /** 'round', 'pointed' or 'flat' heads to the openings. */
    arch?: 'round' | 'pointed' | 'flat';
    /** Height of a course of stone; left out, about an eighth of the wall. */
    course?: number;
    /** How much of the top has fallen, in a ragged line, 0 to 1 (never below the arches' springing). */
    ruin?: number;
    seed?: number;
}

interface CrystalSpec {
    /** Its foot, where it grows out of the rock. */
    at: Vec3;
    /** The way it points. */
    dir: Vec3;
    length: number;
    /** Its radius, corner to middle. */
    r: number;
    /** Sides, 3 to 8 (6 when left out). */
    sides?: number;
    /** How much of its length the point takes, 0.1 to 0.8 (0.3). */
    tip?: number;
    /** How many chips are knocked off its faces, 0 to 6. */
    chips?: number;
    seed: number;
}

interface ClusterSpec {
    /** Where they grow from. */
    at: Vec3;
    count: number;
    /** The longest, in the middle. */
    size: number;
    r: number;
    /** How far the outer ones lean, in degrees (50 when left out). */
    spread?: number;
    sides?: number;
    chips?: number;
    seed: number;
}

interface GeodeSpec {
    at: Vec3;
    r: number;
    /** The way the broken face looks: its outward direction. */
    open: Vec3;
    /** The rind's share of the radius (0.15). */
    rind?: number;
    /** Banded layers inside the rind (3). */
    bands?: number;
    /** How long the crystals lining the hollow are, as a share of the radius (0.22). */
    lining?: number;
    seed: number;
}

interface ColumnsSpec {
    /** The middle of the field, on the ground. */
    at: Vec3;
    /** How far the field reaches. */
    r: number;
    /** A column's width across its flats. */
    cell: number;
    /** The tallest column. */
    height: number;
    /** How heights run: 'dome' (tallest in the middle, as organ pipes), 'steps' (a causeway stepping down to its edge) or 'random'. */
    rise?: 'dome' | 'steps' | 'random';
    seed: number;
}

interface DripsSpec {
    /** The middle of the floor under them. */
    at: Vec3;
    /** How far across they spread. */
    r: number;
    /** The height of the roof they hang from. */
    roof: number;
    count: number;
    /** The longest stalactite. */
    length: number;
    seed: number;
}

function dripPlan(s: DripsSpec): {
    x: number;
    z: number;
    down: number;
    up: number;
    joined: boolean;
    wide: number;
}[];

interface FlowSpec {
    /** The middle of its top, where it leaves the wall. */
    at: Vec3;
    /** Along the wall: [x, z]. Its face looks out to the right of this. */
    along: [number, number];
    width: number;
    /** How far it hangs down. */
    drop: number;
    /** Folds across it (5). */
    folds?: number;
    seed: number;
}

interface IcicleSpec {
    /** About how far apart they hang. */
    every: number;
    /** The longest. */
    length: number;
    /** Only edges higher than this hang icicles (an edge resting on the ground has none): every edge when left out. */
    above?: number;
    seed: number;
}

interface TreeSpec {
    /** The foot of the trunk. */
    at: Vec3;
    /** How high the trunk rises before the crown. */
    height: number;
    /** The crown's radii: the space its branches grow to fill. */
    crown: Vec3;
    /** The trunk's radius at its foot; every limb is as thick as what it carries. */
    r: number;
    /** Points scattered through the crown that the branches grow toward (160). More makes a finer tree. */
    points?: number;
    seed: number;
}

interface TreeNode {
    p: Vec3;
    parent: number;
    r: number;
}

function colonize(s: TreeSpec): {
    nodes: TreeNode[];
    ends: number[];
};

function tree(s: TreeSpec & {
    leaves?: number;
    only?: 'limbs' | 'leaves';
}, thin?: number): Shape;

interface CactusSpec {
    at: Vec3;
    height: number;
    r: number;
    /** Ribs round it (8). */
    ribs?: number;
    /** Arms, 0 to 4. */
    arms?: number;
    seed: number;
}

interface RosetteSpec {
    at: Vec3;
    r: number;
    leaves: number;
    seed: number;
}

interface BracketSpec {
    /** Where the lowest shelf meets the trunk. */
    at: Vec3;
    /** The way the shelves face out from the trunk: [x, z]. */
    facing: [number, number];
    r: number;
    count: number;
    seed: number;
}

interface BrainSpec {
    at: Vec3;
    r: number;
    groove?: number;
    seed: number;
}

interface ShellSpec {
    /** The middle of its coil. */
    at: Vec3;
    /** About its width. */
    size: number;
    /** Whorls (3). */
    turns?: number;
    /** 0 a flat coil (nautilus) to 1 a tall spire (whelk). */
    spire?: number;
    /** Which way it faces, in degrees about the upright. */
    facing?: number;
}

function shellCoil(s: ShellSpec): {
    points: Vec3[];
    radii: number[];
};

interface HornSpec {
    /** The root, on the head. */
    at: Vec3;
    /** The way it first grows. */
    dir: Vec3;
    length: number;
    /** At the root. */
    r: number;
    /** Turns of its curl: 0 straight, 1 a full ram's curl. */
    curl?: number;
    /** How far it winds sideways as it curls, as a corkscrew does, 0 to 1. */
    twist?: number;
    /** Rings round it (12). */
    ridges?: number;
}

function hornPath(s: HornSpec): {
    points: Vec3[];
    radii: number[];
};

interface AntlerSpec {
    at: Vec3;
    /** The way the main beam leaves the head. */
    dir: Vec3;
    length: number;
    r: number;
    /** Tines off the main beam, 1 to 8. */
    tines: number;
    seed: number;
}

interface RibsSpec {
    /** The ends of the spine. */
    from: Vec3;
    to: Vec3;
    /** Pairs of ribs. */
    count: number;
    /** How far out each side the widest rib reaches. */
    span: number;
    /** How far down they curve. */
    drop: number;
    /** A rib's radius. */
    r: number;
}

interface Bed {
    thick: number;
    hard: number;
}

interface LandSpec {
    /** The middle of its foot. */
    at: Vec3;
    /** Half its size along x and z. */
    half: [number, number];
    /** Hills: each a place, a height and a reach. */
    peaks: {
        at: [number, number];
        h: number;
        r: number;
    }[];
    /** Rough ground over the hills, as a height. */
    noise?: number;
    /** Water drops that run down it, each wearing it and dropping what it carries where it slows (0 to MAX_DROPS). */
    drops?: number;
    /** How far slopes slump to scree, 0 to 1. */
    slump?: number;
    /** Beds of rock, from the bottom up, repeating: soft ones wear faster. Left out, all one rock. */
    beds?: Bed[];
    seed: number;
}

interface Land {
    nx: number;
    nz: number;
    cell: number;
    x0: number;
    z0: number;
    /** Heights above the foot, nx by nz. */
    height: Float32Array;
    /** Where water ran (a running total of how much and how fast). */
    flow: Float32Array;
    /** What was laid down: fans where water slowed, scree where slopes slid. */
    laid: Float32Array;
    /** How much laid down counts as a fan or scree, not a dusting. */
    thick: number;
    /** Height at (x, z) in the land's own frame (above its foot), smoothly between grid points. */
    at(x: number, z: number): number;
}

function land(s: LandSpec & {
    base?: number;
}): Shape;

interface ButteSpec {
    /** The middle of its foot. */
    at: Vec3;
    r: number;
    height: number;
    beds?: Bed[];
    /** How far each soft bed is worn back, as a share of the radius (0.3). */
    wear?: number;
    /** A caprock this much wider than the rock under it, as a share (0: none). */
    cap?: number;
    seed: number;
}

function hoodoo(s: {
    at: Vec3;
    height: number;
    r: number;
    seed: number;
}): Shape;

interface ArchSpec {
    /** The feet of its two legs, on the ground. */
    from: Vec3;
    to: Vec3;
    height: number;
    /** How thick the fin of rock is. */
    thick: number;
    /** How high the soft bed the hole wore through sits: its middle, as a share of the height (0.4). */
    soft?: number;
    beds?: Bed[];
    seed: number;
}

interface MudSpec {
    /** The middle of the patch, on the ground. */
    at: Vec3;
    r: number;
    /** About how wide a plate is. */
    plate: number;
    /** How far plate edges curl up, 0 to 1. */
    curl?: number;
    seed: number;
}

interface PebbleSpec {
    /** The stream's line, on the ground. */
    path: Vec3[];
    width: number;
    count: number;
    /** The biggest pebble, mid-stream. */
    size: number;
    seed: number;
}

function pebbleList(s: PebbleSpec): {
    at: Vec3;
    r: Vec3;
}[];

interface Grower {
    style: GrowStyle;
    /** Where it stands. */
    at: Vec3;
    seed: number;
    /** The trunk's length (a crystal's longest spike). */
    size: number;
    /** The trunk's radius at the foot. */
    r: number;
    /** Times it splits; left out, what suits the style. */
    depth?: number;
    /** Branches from each split; left out, what suits the style. */
    branches?: number;
}

interface Twig {
    from: Vec3;
    to: Vec3;
    r: number;
    rTo: number;
}

function grow(g: Grower): {
    twigs: Twig[];
    tips: Vec3[];
};

function growBounds(g: Grower): {
    mid: Vec3;
    half: Vec3;
};

function fallAt(kind: Falling, life: number): {
    drop: number;
    lying: boolean;
    size: number;
};

interface DriftSpec {
    /** The middle of the snow field, at about ground height. */
    at: Vec3;
    /** Half its size along x and z. */
    half: [number, number];
    /** How deep snow lies on open, level ground. */
    depth: number;
    /** Which way the wind blows, [x, z]; the drift piles downwind of what stands in its way. */
    wind: [number, number];
    /** The most it piles up against something (3 × depth). */
    pile?: number;
    /** How far downwind a wall still shelters, in multiples of its height (4). */
    reach?: number;
    /** A path trodden through it, where it lies thin. */
    path?: Vec3[];
    pathWidth?: number;
    seed: number;
}

interface Drift {
    nx: number;
    nz: number;
    cell: number;
    x0: number;
    z0: number;
    /** The ground under the snow. */
    ground: Float32Array;
    /** How deep the snow is on it. */
    depth: Float32Array;
}

interface FrostSpec {
    /** Where it starts, on the surface. */
    at: Vec3;
    /** The way the surface faces. */
    facing: Vec3;
    /** How far it spreads. */
    r: number;
    /** Main branches out from the start (5). */
    arms?: number;
    /** Which share of its growth to show, [from, to] in 0..1 (all of it): split one fern over parts that sprout in turn and it grows a branch at a time. */
    stage?: [number, number];
    seed: number;
}

interface FrostBranch {
    from: Vec3;
    to: Vec3;
    r: number;
    gen: number;
    t: number;
}

interface SceneDoc {
    name: string;
    /** Seconds before everything repeats: 4 to 60. */
    loop: number;
    /**
     * The baked sun: `from` points toward it. `ramp` (0–1, 0.7 when left out) turns shade toward cool violet and full
     * sun toward warm yellow, as a painter's ramp does; `crevice` (0.5) darkens corners and cracks; `wear` (0.5)
     * lightens sharp outer edges. 0 turns any of them off. `bounce` (off unless set) lets surfaces throw their color onto
     * what faces them, as a red wall warms the floor beside it; it costs build time, so use it where it shows.
     */
    light?: {
        from?: Vec3;
        ambient?: number;
        shadow?: number;
        ramp?: number;
        crevice?: number;
        wear?: number;
        bounce?: number;
    };
    /** The colors the picture is drawn in, 2 to 32. */
    palette: string[];
    /** The sky behind, top and bottom. Left out, the background is clear. */
    sky?: [string, string];
    /** How far down the picture the sky's blend runs before it is all the bottom color: 0.05 to 1, the whole way when left out. */
    skyReach?: number;
    look?: {
        dither?: number;
        glow?: number;
        outline?: boolean;
        edges?: boolean;
    };
    /**
     * How wide each surface disc is, as a share of the grid: 0.4 to 1, 0.55 when left out. Small discs keep paint
     * crisp but let about a tenth of what lies behind a surface show through; a subject whose far side or inner
     * parts are much darker or lighter than its near side (a head over an open jaw) wants 0.75, as creatures use.
     */
    disc?: number;
    /** Where the view starts. `swing` rocks it gently from side to side by that many degrees, once a loop. */
    camera: Orbit & {
        swing?: number;
    };
    /** Things that move. The land itself needs none: parts with no bone stand still. */
    bones?: BoneDoc[];
    parts: PartDoc[];
    moves?: MoveDoc[];
    /** Live lights, at most four: they light what is near them, frame by frame. */
    lights?: LightDoc[];
    /** What hangs in the air: distance haze, low mist, beams of light and drifting specks. */
    air?: AirDoc;
    /**
     * Snow, moss or dust laid over everything once it is cut (parts marked `bare` and glowing ones keep their paint):
     * `snow` settles on tops open to the sky, `moss` creeps over shut-in and up-turned faces in patches, `dust` lies
     * thin on every upturned face. `amount` 0 to 1, from a dusting to most of what faces up.
     */
    cover?: {
        kind: 'snow' | 'moss' | 'dust';
        color: string;
        amount: number;
    };
    /** Where the eye goes: within `r` of `at` the scene is cut at full detail, further out on a grid twice as coarse, in about a quarter of the blobs. */
    focus?: {
        at: Vec3;
        r: number;
    };
}

interface AirDoc {
    /** Things far from the camera fade toward `color`: it starts `from` units past the view's target (0 when left out) and would be total at `to` (4). */
    haze?: {
        color: string;
        from?: number;
        to?: number;
    };
    /** Low banks of mist that drift slowly to and fro, at most four. */
    mist?: MistDoc[];
    /** Beams of light, as from a window or a gap in the leaves, at most six: what they land on is lit by them. */
    shafts?: ShaftDoc[];
    /** Swarms of small things, each moving on its own, at most eight swarms and 300 specks in all. */
    specks?: SpeckDoc[];
}

interface MistDoc {
    /** The middle of the bank. */
    at: Vec3;
    /** Half its size along x, y (its depth) and z. */
    half: Vec3;
    color: string;
    /** How thick it is, 0 to 1 (0.5 when left out). */
    thick?: number;
}

interface ShaftDoc {
    /** Where it starts (a window, a crack, a lamp) and where it lands. */
    from: Vec3;
    to: Vec3;
    /** How wide it is, as a radius. */
    r: number;
    color: string;
    /** How bright, 0 to 1 (0.6 when left out). */
    strength?: number;
}

interface SpeckDoc {
    kind: SpeckKind;
    count: number;
    /** Two opposite corners of the box they live in: rain and snow fall from its top to its bottom, embers and bubbles rise from its bottom to its top. */
    from: Vec3;
    to: Vec3;
    /** Each speck takes one of these. */
    colors: string[];
    /** A speck's radius; left out, a size that suits the kind. */
    size?: number;
    /** Whether they give off light; left out, embers and fireflies do. */
    glow?: boolean;
    /** Rain, snow and leaves only: each lands on whatever stands still under it (or the box's floor), lies a while and goes, then falls again. */
    land?: boolean;
    /** Rain, snow and leaves only: how far the wind carries each sideways over its whole fall, [x, z]; rain slants along it. */
    wind?: [number, number];
}

interface BoneDoc {
    name: string;
    /** The point it turns and grows about. */
    at: Vec3;
    /** Another bone it rides on (named earlier in the list). */
    parent?: string;
}

interface PartDoc {
    shape: ShapeDoc;
    paint: PaintDoc;
    /** The bone that carries it; left out, it is part of the land. */
    bone?: string;
    /** Gives off light and takes none: lamps, fire, stars, anything that must stay bright. */
    glow?: boolean;
    /** Casts no shadow: thin things in the air. */
    noShadow?: boolean;
    /** A color that gathers in its corners and cracks, as moss or soot does. */
    grime?: string;
    /** Takes none of the scene's `cover`: water, glass, a fresh fire. */
    bare?: boolean;
    /**
     * Little drawn marks over it, one in some 4-by-4 blocks of pixels, never repeating: `hatch`, `stipple`, `cracks`,
     * `grain` (wood), `tufts` (grass) or `scales`. `amount` (0.5) is the share of blocks marked; `color` the ink, a
     * darker step of the paint when left out.
     */
    ink?: {
        kind: 'hatch' | 'stipple' | 'cracks' | 'grain' | 'tufts' | 'scales';
        amount?: number;
        color?: string;
    };
    /**
     * Water, ice or glass: it shows what lies behind it (`see`, 0.6) and mirrors what is over it (`mirror`, 0.3, more
     * at a glancing look), painted for the scene's own camera. Its paint tints what shows through, and where the line
     * from the eye leaves it with nothing met, a darker step of it shows, as the bottom of a pond does. `top` keeps it
     * to upturned faces, for a pond cut as one slab with earth sides.
     */
    glass?: {
        see?: number;
        mirror?: number;
        top?: boolean;
    };
    /** Dabs that follow the form: 0 to 1, how far each cell is drawn as a stroke along the level line round the shape. Shows as brushwork in the Blobs view. */
    strokes?: number;
}

type ShapeDoc = {
    kind: 'sphere';
    at: Vec3;
    r: number;
}

type PaintDoc = string
/** Stripes across an axis, `size` thick, taking the colors in turn. */
 | {
    kind: 'bands';
    axis: 'x' | 'y' | 'z';
    size: number;
    colors: string[];
}

type MoveDoc = 
/** Turns right round, `times` per loop (negative turns the other way). */
{
    kind: 'spin';
    bone: string;
    axis: 'x' | 'y' | 'z';
    times: number;
    phase?: number;
}

interface LightDoc {
    at: Vec3;
    color: string;
    /** 1 is a torch; 3 lights dark ground brightly. */
    strength: number;
    /** How far it reaches. */
    range: number;
    /** Flickers by this share of its strength, `times` per loop. */
    flicker?: {
        by: number;
        times: number;
    };
    /** Goes round a circle of this radius about `at`, `times` per loop. */
    circle?: {
        r: number;
        times: number;
    };
    /**
     * Casts shadows, worked out once when the scene is built, so they cost nothing as it plays and flicker with it. Only
     * the first four lights can, and not one that goes round a circle. Give it to a lamp or fire out in the open: a light
     * set inside something (a jar, a window, a hollow) to stand for its glow would shade everything outside.
     */
    shadows?: boolean;
}

interface CompiledScene {
    name: string;
    loop: number;
    orbit: Orbit;
    /** Degrees the view rocks to either side, once a loop: 0 holds still. */
    swing: number;
    /** The pixel look the scene asks for. */
    look: PixelLook;
    palette: Rgb[];
    bones: Bone[];
    /** The shapes on a grid of `spacing`. */
    spec(spacing: number): VoxelSpec;
    /** The parts (by their place in the list) that came out with no blobs at all, such as a shape whose hole swallows it: `checkScene` can't see those. */
    empty(built: {
        partOf: ArrayLike<number>;
    }): number[];
    /** Poses the bones for `t` seconds. */
    pose(sk: Skeleton, t: number): void;
    lights(t: number): PointLight[];
    /** Distance haze, if the scene asks for it: the color (linear) and where it starts and would be total, in units past the view's target. */
    haze?: {
        color: Vec3;
        from: number;
        to: number;
    };
}

function compileScene(doc: SceneDoc, { puffs }?: {
    puffs?: boolean;
}): CompiledScene;

interface MpmOptions {
    /** Grid cells a side. */
    cells?: number;
    /** Most particles it can hold. */
    capacity?: number;
    /** Seconds per substep. */
    dt?: number;
    /** Downward pull, box sides per second squared. */
    gravity?: number;
    /** Sand's friction angle in degrees: the steepest slope a pile keeps. */
    friction?: number;
}

class Mpm {
    readonly n: number;
    readonly dx: number;
    readonly capacity: number;
    dt: number;
    gravity: number;
    count: number;
    /** Particle state. */
    readonly x: Float64Array;
    readonly v: Float64Array;
    readonly C: Float64Array;
    readonly F: Float64Array;
    /** Kirchhoff stress from the last step's F, so each step needs one decomposition. */
    readonly tau: Float64Array;
    readonly Jp: Float64Array;
    readonly mat: Uint8Array;
    /** Grid: velocity (momentum while scattering) and mass. */
    readonly gv: Float64Array;
    readonly gm: Float64Array;
    readonly mass: number;
    readonly volume: number;
    time: number;
    constructor(o?: MpmOptions);
    setFriction(degrees: number): void;
    /** Adds one particle, still and unstrained. Returns false when full. */
    add(p: ArrayLike<number>, m: Material, vel?: ArrayLike<number>): boolean;
    /** Fills a box (corners in box units) with particles on a jittered lattice, `PER_CELL` a cell a side. Returns how many went in. */
    fillBox(lo: ArrayLike<number>, hi: ArrayLike<number>, m: Material, seed?: number, vel?: ArrayLike<number>): number;
    /** Pushes everything within `r` of `at` by `v` (box sides a second) on the next step. */
    poke(at: [number, number, number], r: number, v: [number, number, number]): void;
    /** Empties the box. */
    clear(): void;
    /** Total mass on the grid after the last scatter, for tests. */
    gridMass(): number;
    /** Runs whole substeps for `seconds`. */
    advance(seconds: number): void;
    step(): void;
}

class PixelPass {
    /** The scene, drawn small. Linear and premultiplied, as any render target. */
    readonly small: RenderTarget<import("three").Texture<unknown, import("three").TextureEventMap>, import("three").RenderTargetEventMap>;
    /** The scene's parts, drawn small (`SplatWorld.parts`): where the color changes, one part ends and another begins. Only drawn for a look with `parts`. */
    readonly ids: RenderTarget<import("three").Texture<unknown, import("three").TextureEventMap>, import("three").RenderTargetEventMap>;
    constructor(look: PixelLook);
    /** The finished art at its own size, in display color, for reading back (tests, saving) and for the screen. */
    get art(): RenderTarget<import("three").Texture<unknown, import("three").TextureEventMap>, import("three").RenderTargetEventMap>;
    /** The art of the frame before, when this frame was drawn against it (a look with `steady`): what `pixelArt` needs to give the same answer. */
    get before(): RenderTarget<import("three").Texture<unknown, import("three").TextureEventMap>, import("three").RenderTargetEventMap> | undefined;
    /** Forgets the frame before: for when what is being drawn is swapped for something else. */
    reset(): void;
    /** The look in use. */
    look: PixelLook;
    setLook(look: PixelLook): void;
    /** The art's size in pixels. */
    setSize(width: number, height: number): void;
    get width(): number;
    get height(): number;
    /**
     * Draws `scene` as pixel art. With `screen` (the output's size in device
     * pixels and how many of them make one art pixel) it goes to the renderer's
     * current output; without, into `art` at one to one.
     */
    render(renderer: WebGPURenderer, scene: Object3D, camera: Camera, screen?: {
        width: number;
        height: number;
        scale: number;
    }): void;
    dispose(): void;
}

interface PixelLook {
    /** The colors every pixel snaps to; empty keeps the scene's own colors. */
    palette: Rgb[];
    /** 0..1, as for `quantize`. */
    dither: number;
    /** A 1-pixel line round the scene's silhouette, or none. */
    outline: Rgb | null;
    /** How far bright pixels spill light onto their neighbors: 0 is none. */
    glow: number;
    /** Lines inside the scene, where one color meets a much lighter one: 0 (or left out) is none, 1 the darkest line. */
    edges?: number;
    /**
     * A line where one part of the scene meets another whose color is too close for `edges` to draw one (two things of one color, one in front of the other), at `edges`' strength or full strength without it.
     * Needs a map of the parts drawn beside the scene (`pixelArt`'s `parts`; the live pass draws its own).
     */
    parts?: boolean;
    /**
     * A backdrop behind the scene: its color at the top and at the bottom of the picture, blended between and dithered into the palette.
     * `reach` is how far down the picture the blend runs before it is all the bottom color (above 0, up to 1; the whole way when left out or not a sound number: `skyReach`).
     * Left out, empty pixels stay clear.
     */
    sky?: [top: Rgb, bottom: Rgb, reach?: number];
    /**
     * Steady pixels: a pixel keeps the palette color it had in the frame before unless another is closer by more than this (an OKLab distance; 0 or left out is off).
     * Without it, a pixel that sits between two colors flips back and forth as lights flicker and the view turns.
     */
    steady?: number;
    /**
     * Lone-pixel cleanup, as a pixel artist does it: a scene pixel whose color none of its eight neighbors shares, while
     * six or more of them share one other color, takes that color. With a map of parts, only a pixel inside its own
     * part (four or more neighbors of its part) is touched, so a speck, an eye or a firefly in front of something stays.
     * A checkerboard dither keeps its pixels: each has its own color on the diagonals.
     */
    tidy?: boolean;
}

interface Frame {
    width: number;
    height: number;
    /** RGBA, row 0 at the top, straight (not premultiplied) alpha. */
    data: Uint8ClampedArray;
}

interface DetailRule {
    /**
     * Blobs wanted per pixel of the disc round the actor on screen. The disc is a loose fit (a long creature seen end on
     * fills a third of it), about half the blobs face away, and blobs overlap, so one per disc pixel still looks whole.
     */
    density: number;
    /** Never fewer than this share of the blobs. */
    min: number;
}

interface ShapeEdit {
    shape: 'sphere' | 'box';
    /** World position of the shape's middle. */
    center: [number, number, number];
    /** A sphere's radius (the first value), or a box's half sizes. */
    size: [number, number, number];
    op: 'cut' | 'paint';
    /** Act on what's outside the shape instead: a cut that keeps only the inside is a crop. */
    outside?: boolean;
    /** Paint: the color, in sRGB 0–1 like a blob's own. */
    color?: [number, number, number];
    /** Paint: how far toward the color, 0–1 (default 1). */
    amount?: number;
    /** Paint: how far in from the edge it takes to reach full strength, in units (default 0, a hard edge). */
    soft?: number;
}

function editAt(edits: readonly ShapeEdit[], p: ArrayLike<number>): {
    keep: boolean;
    paint: [number, number, number];
    amount: number;
};

class SplatDepth {
    readonly target: RenderTarget;
    constructor(width?: number, height?: number);
    setSize(width: number, height: number): void;
    /** Draws the depth map of `scene` as just rendered from `camera` into `target` (sized to match the frame first). */
    render(renderer: WebGPURenderer, scene: Object3D, camera: Camera): void;
    /** For tests and tools: the map read back, one depth a pixel, rows from the top. */
    read(renderer: WebGPURenderer): Promise<{
        width: number;
        height: number;
        depth: Float32Array;
    }>;
    dispose(): void;
}

const SKIN_RULE: {
    readonly rotationBlend: 'quaternionAverage';
    readonly scaleBlend: 'weightedAverage';
};

interface Clip {
    name: string;
    /** Seconds. */
    times: Float32Array;
    /** Per bone, a rotation key per time (x, y, z, w). */
    rotations: Float32Array[];
    /** Per bone that moves, an offset key per time (x, y, z) on top of its rest place; missing for bones that never move. */
    offsets?: (Float32Array | undefined)[];
    /** Per bone that grows or shrinks, a uniform scale key per time; missing for bones that keep their size. */
    sizes?: (Float32Array | undefined)[];
    /** Each morph's weight per time (times × morphs, a key's weights together); missing for a clip that leaves them at 0. */
    weights?: Float32Array;
}

interface Rigged {
    name: string;
    blobs: Blobs;
    skin: Skin;
    skeleton: Skeleton;
    clips: Clip[];
    /** Blend shapes on the blobs (morph.ts), applied to the rest blobs before skinning; clips key their weights. */
    morphs?: Morph[];
